<?php
require_once __DIR__.'/app/lib/Db.php';
$config=require __DIR__.'/app/config.php';
$pdo=Db::pdo();
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function status_label($v){return ucwords(str_replace('_',' ',(string)$v));}
function pct($v){return (int)round(((float)$v)*100);}
function status_class($v){return in_array($v,['supported'],true)?'ok':(in_array($v,['partially_supported','enterprise_only','plan_dependent','custom_configuration','addon','third_party_integration'],true)?'partial':(in_array($v,['not_supported'],true)?'no':'unknown'));}
function icon_svg($category){
  $map=[
    'crm'=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm10 1a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM1 21v-2a6 6 0 0 1 12 0v2M13 21v-1a5 5 0 0 1 9-3"/></svg>',
    'hr-hcm'=>'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg>',
    'itsm'=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v12H4zM8 21h8M12 17v4"/><path d="M8 9h8M8 13h5"/></svg>',
    'erp'=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 21h18M5 21V9l7-5 7 5v12M9 21v-6h6v6"/><path d="M8 10h2M14 10h2"/></svg>',
    'project-management'=>'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h5M8 16h3"/><path d="m15 16 1.5 1.5L20 14"/></svg>',
    'corporate-identity-digital-business-cards'=>'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="8" cy="11" r="2"/><path d="M5.5 16c.7-2 4.3-2 5 0M13 10h5M13 14h5"/></svg>'
  ];
  return $map[$category]??'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 3 8l9 5 9-5-9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/></svg>';
}
function initials($name){$parts=preg_split('/\s+/',trim($name));$out='';foreach(array_slice($parts,0,2) as $x){if($x!=='')$out.=mb_strtoupper(mb_substr($x,0,1));}return $out?:'TS';}
if(!preg_match('#^/software/([a-z0-9-]+)/?$#',$path,$m)){http_response_code(404);exit('Not found');}
$st=$pdo->prepare("SELECT p.*,v.name vendor,v.website_url vendor_website,c.name category,c.slug category_slug FROM products p LEFT JOIN vendors v ON v.id=p.vendor_id LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.status='active' LIMIT 1");
$st->execute([$m[1]]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Not found');}
$q=$pdo->prepare("SELECT cap.name,cap.slug,cap.description,mo.name module,pc.support_status,pc.implementation_type,pc.limitations,pc.confidence_score,pc.last_verified_at FROM product_capabilities pc JOIN capabilities cap ON cap.id=pc.capability_id JOIN modules mo ON mo.id=cap.module_id WHERE pc.product_id=? AND pc.edition_id IS NULL ORDER BY mo.name,cap.name");$q->execute([$p['id']]);$caps=$q->fetchAll();
$q=$pdo->prepare("SELECT i.name,i.slug,pi.support_status,pi.confidence_score FROM product_integrations pi JOIN integrations i ON i.id=pi.integration_id WHERE pi.product_id=? ORDER BY i.name");$q->execute([$p['id']]);$ints=$q->fetchAll();
$q=$pdo->prepare("SELECT d.name,d.slug,pd.support_status,pd.confidence_score FROM product_deployments pd JOIN deployment_models d ON d.id=pd.deployment_model_id WHERE pd.product_id=? ORDER BY d.name");$q->execute([$p['id']]);$deps=$q->fetchAll();
$q=$pdo->prepare("SELECT pe.name,pe.slug,pe.sort_order FROM product_editions pe WHERE pe.product_id=? AND pe.status='active' ORDER BY pe.sort_order,pe.name");$q->execute([$p['id']]);$editions=$q->fetchAll();
$q=$pdo->prepare("SELECT pp.pricing_model,pp.billing_period,pp.currency,pp.amount_min,pp.amount_max,pp.unit_label,pp.notes,pp.source_url,pp.last_verified_at,pe.name edition_name FROM product_pricing pp LEFT JOIN product_editions pe ON pe.id=pp.edition_id WHERE pp.product_id=? ORDER BY COALESCE(pp.amount_min,999999999),pe.sort_order");$q->execute([$p['id']]);$pricing=$q->fetchAll();
$q=$pdo->prepare("SELECT source_title,source_url,source_type,verification_status,confidence,checked_at,publisher_name FROM evidence_sources WHERE product_id=? ORDER BY checked_at DESC");$q->execute([$p['id']]);$evidence=$q->fetchAll();
$q=$pdo->prepare("SELECT p2.name,p2.slug,p2.short_description FROM products p2 WHERE p2.category_id=? AND p2.id<>? AND p2.status='active' ORDER BY p2.name LIMIT 6");$q->execute([$p['category_id'],$p['id']]);$alts=$q->fetchAll();
$known=0;$supported=0;$unknown=0;$conf=[];$modules=[];
foreach($caps as $x){$modules[$x['module']][]=$x;if(in_array($x['support_status'],['unknown','not_yet_verified'],true))$unknown++;else{$known++;$conf[]=(float)$x['confidence_score'];}if($x['support_status']==='supported')$supported++;}
$avgConf=$conf?round(array_sum($conf)/count($conf)*100):0;
$desc=$p['short_description']?:('Evidence-backed review of '.$p['name'].' capabilities, integrations, deployment options and limitations.');
$canonical=$config['site_url'].'/software/'.$p['slug'];
$softwareLd=['@context'=>'https://schema.org','@type'=>'SoftwareApplication','name'=>$p['name'],'applicationCategory'=>$p['category'],'url'=>$canonical,'description'=>$desc,'publisher'=>['@type'=>'Organization','name'=>$p['vendor']]];
$crumb=['@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>[
 ['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>$config['site_url'].'/'],
 ['@type'=>'ListItem','position'=>2,'name'=>'Software','item'=>$config['site_url'].'/software'],
 ['@type'=>'ListItem','position'=>3,'name'=>$p['name'],'item'=>$canonical]
]];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title><?=e($p['name'])?> Review, Features, Pricing & Evidence | TechSelectAI</title>
<meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e($canonical)?>">
<meta property="og:type" content="website"><meta property="og:title" content="<?=e($p['name'])?> Review | TechSelectAI"><meta property="og:description" content="<?=e($desc)?>"><meta property="og:url" content="<?=e($canonical)?>">
<script type="application/ld+json"><?=json_encode($crumb,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><script type="application/ld+json"><?=json_encode($softwareLd,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script>
<style>
:root{--navy:#123b67;--teal:#00a7b5;--ink:#172033;--muted:#64748b;--line:#e2e8f0;--soft:#f7fafc;--green:#137a55;--greenbg:#e9f8f1;--amber:#95610a;--amberbg:#fff7df;--red:#b42318;--redbg:#fff0ee}
*{box-sizing:border-box}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;margin:0;color:var(--ink);background:#fff}a{color:#145ea8}header{display:flex;justify-content:space-between;align-items:center;padding:17px max(24px,5vw);border-bottom:1px solid var(--line);background:#fff;position:sticky;top:0;z-index:5}header>a{font-size:20px;font-weight:800;color:var(--navy);text-decoration:none}nav a{margin-left:20px;text-decoration:none;font-weight:650;color:#334155}.wrap{max-width:1160px;margin:auto;padding:0 24px}.crumbs{font-size:13px;color:var(--muted);padding-top:25px}.hero{display:grid;grid-template-columns:auto 1fr auto;gap:22px;align-items:center;padding:30px 0 22px}.product-mark{width:86px;height:86px;border-radius:22px;background:linear-gradient(145deg,#edf8fa,#eaf1f8);border:1px solid #d8e6ee;display:grid;place-items:center;position:relative}.product-mark svg{width:44px;height:44px;fill:none;stroke:var(--navy);stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.product-mark b{position:absolute;right:-7px;bottom:-7px;width:34px;height:34px;border-radius:12px;background:var(--navy);color:#fff;display:grid;place-items:center;font-size:11px;border:3px solid #fff}.eyebrow{font-size:12px;letter-spacing:.09em;text-transform:uppercase;color:#52708b;font-weight:800}.hero h1{font-size:clamp(34px,5vw,54px);line-height:1.02;margin:7px 0 10px}.lead{font-size:18px;line-height:1.65;color:#536174;max-width:780px;margin:0}.hero-actions{display:flex;flex-direction:column;gap:10px;min-width:180px}.btn{display:inline-flex;align-items:center;justify-content:center;padding:11px 16px;border-radius:10px;text-decoration:none;font-weight:750}.btn.primary{background:var(--navy);color:#fff}.btn.secondary{border:1px solid #cbd5e1;color:var(--navy);background:#fff}.summary{display:grid;grid-template-columns:repeat(5,1fr);border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#fff;box-shadow:0 8px 25px rgba(15,23,42,.04)}.metric{padding:18px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.metric .label{font-size:12px;color:var(--muted);margin-bottom:7px}.metric strong{font-size:20px}.section{padding-top:36px}.section h2{font-size:27px;margin:0 0 8px}.section-intro{margin:0 0 18px;color:var(--muted);line-height:1.6}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.card{border:1px solid var(--line);border-radius:14px;padding:17px;background:#fff;text-decoration:none;color:inherit}.card h3{font-size:16px;margin:0 0 8px}.card p{margin:5px 0;color:var(--muted);line-height:1.5}.facts{display:grid;grid-template-columns:1fr 1fr;gap:18px}.module{border:1px solid var(--line);border-radius:15px;overflow:hidden;margin-bottom:16px}.module h3{margin:0;padding:14px 17px;background:var(--soft);font-size:16px;border-bottom:1px solid var(--line)}.cap{display:grid;grid-template-columns:minmax(220px,1.5fr) 150px 110px;gap:14px;padding:14px 17px;border-bottom:1px solid #edf1f5;align-items:start}.cap:last-child{border-bottom:0}.cap-name{font-weight:700}.cap small{display:block;margin-top:5px;color:var(--muted);line-height:1.45}.badge{display:inline-block;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800}.badge.ok{color:var(--green);background:var(--greenbg)}.badge.partial{color:var(--amber);background:var(--amberbg)}.badge.no{color:var(--red);background:var(--redbg)}.badge.unknown{color:#596579;background:#eef2f7}.evidence{display:grid;gap:10px}.source{display:flex;gap:12px;border:1px solid var(--line);border-radius:12px;padding:14px}.source-icon{width:34px;height:34px;border-radius:9px;background:#eef6fa;display:grid;place-items:center;color:var(--navy);font-weight:800;flex:0 0 auto}.source p{margin:4px 0;color:var(--muted);font-size:13px}.pricing-table{width:100%;border-collapse:collapse;border:1px solid var(--line);border-radius:14px;overflow:hidden}.pricing-table th,.pricing-table td{text-align:left;padding:13px;border-bottom:1px solid var(--line)}.pricing-table th{background:var(--soft);font-size:12px;color:#526071}.notice{padding:14px 16px;background:#f8fbfd;border:1px solid #dbe8ef;border-radius:12px;color:#536174}.cta{margin-top:42px;padding:26px;border-radius:17px;background:linear-gradient(135deg,#f0f8fb,#f5f8fc);border:1px solid #d5e5ed}.cta h2{margin:5px 0 9px}.cta p{color:#536174;max-width:760px}.alt-head{display:flex;align-items:center;gap:12px}.mini-mark{width:38px;height:38px;border-radius:10px;background:#eef5f8;color:var(--navy);display:grid;place-items:center;font-weight:800}footer{margin:58px 0 30px;color:var(--muted);font-size:13px}@media(max-width:850px){.hero{grid-template-columns:auto 1fr}.hero-actions{grid-column:1/-1;flex-direction:row}.summary{grid-template-columns:repeat(2,1fr)}.metric{border-bottom:1px solid var(--line)}.facts{grid-template-columns:1fr}.cap{grid-template-columns:1fr 120px}.cap>:last-child{grid-column:1/-1}}@media(max-width:560px){nav{display:none}.hero{grid-template-columns:1fr}.product-mark{width:70px;height:70px}.summary{grid-template-columns:1fr}.metric{border-right:0}.hero-actions{flex-direction:column}.cap{grid-template-columns:1fr}}
</style></head><body>
<header><a href="/">TechSelectAI</a><nav><a href="/software">Software</a><a href="/categories/<?=e($p['category_slug'])?>"><?=e($p['category'])?></a><a href="/methodology">Methodology</a><a href="/">Get Advice</a></nav></header>
<main class="wrap"><div class="crumbs"><a href="/">Home</a> / <a href="/software">Software</a> / <?=e($p['name'])?></div>
<section class="hero"><div class="product-mark"><?=icon_svg($p['category_slug'])?><b><?=e(initials($p['name']))?></b></div><div><div class="eyebrow"><?=e($p['category'])?> · <?=e($p['vendor'])?></div><h1><?=e($p['name'])?></h1><p class="lead"><?=e($desc)?></p></div><div class="hero-actions"><?php if($p['website_url']):?><a class="btn secondary" href="<?=e($p['website_url'])?>" target="_blank" rel="nofollow noopener">Official website ↗</a><?php endif;?><a class="btn primary" href="/?considering=<?=rawurlencode($p['name'])?>">Evaluate for my company</a></div></section>
<section class="summary"><div class="metric"><div class="label">Vendor</div><strong><?=e($p['vendor']?:'Not recorded')?></strong></div><div class="metric"><div class="label">Verified capabilities</div><strong><?=$known?></strong></div><div class="metric"><div class="label">Supported</div><strong><?=$supported?></strong></div><div class="metric"><div class="label">Evidence confidence</div><strong><?=$avgConf?>%</strong></div><div class="metric"><div class="label">Last reviewed</div><strong style="font-size:15px"><?=e($p['last_reviewed_at']?date('M j, Y',strtotime($p['last_reviewed_at'])):'Not recorded')?></strong></div></section>
<section class="section"><h2>At a glance</h2><p class="section-intro">A structured summary from the TechSelectAI knowledge base. Product fit depends on your specific requirements, deployment model, integrations and commercial constraints.</p><div class="facts"><div class="card"><h3>Category</h3><p><a href="/categories/<?=e($p['category_slug'])?>"><?=e($p['category'])?></a></p></div><div class="card"><h3>Evidence coverage</h3><p><?=count($evidence)?> published source<?=count($evidence)===1?'':'s'?> · <?=$unknown?> capability fact<?=($unknown===1?'':'s')?> still unknown/not verified.</p></div><?php if($deps):?><div class="card"><h3>Deployment options</h3><p><?php foreach($deps as $i=>$x){if($i)echo ' · ';echo e($x['name']).' ('.e(status_label($x['support_status'])).')';}?></p></div><?php endif;?><?php if($editions):?><div class="card"><h3>Plans / editions</h3><p><?=e(implode(' · ',array_column($editions,'name')))?></p></div><?php endif;?></div></section>
<section class="section"><h2>Capabilities</h2><p class="section-intro">Capabilities are grouped by business area. “Not yet verified” means evidence is incomplete; it is not the same as “not supported”.</p><?php if(!$caps):?><div class="notice">Capability coverage has not been published for this product yet.</div><?php else:?><?php foreach($modules as $module=>$rows):?><div class="module"><h3><?=e($module)?></h3><?php foreach($rows as $x):?><div class="cap"><div><a class="cap-name" href="/capabilities/<?=e($x['slug'])?>"><?=e($x['name'])?></a><?php if($x['limitations']):?><small><?=e($x['limitations'])?></small><?php elseif($x['description']):?><small><?=e($x['description'])?></small><?php endif;?></div><div><span class="badge <?=status_class($x['support_status'])?>"><?=e(status_label($x['support_status']))?></span></div><div><strong><?=pct($x['confidence_score'])?>%</strong><small>confidence</small></div></div><?php endforeach;?></div><?php endforeach;?><?php endif;?></section>
<?php if($ints||$deps):?><section class="section"><h2>Integrations & deployment</h2><div class="grid"><?php foreach($ints as $x):?><a class="card" href="/integrations/<?=e($x['slug'])?>"><h3>↔ <?=e($x['name'])?></h3><p><span class="badge <?=status_class($x['support_status'])?>"><?=e(status_label($x['support_status']))?></span> · <?=pct($x['confidence_score'])?>% confidence</p></a><?php endforeach;?><?php foreach($deps as $x):?><div class="card"><h3>▣ <?=e($x['name'])?></h3><p><span class="badge <?=status_class($x['support_status'])?>"><?=e(status_label($x['support_status']))?></span> · <?=pct($x['confidence_score'])?>% confidence</p></div><?php endforeach;?></div></section><?php endif;?>
<section class="section"><h2>Pricing & editions</h2><?php if($pricing):?><table class="pricing-table"><thead><tr><th>Edition</th><th>Pricing model</th><th>Price</th><th>Billing</th><th>Last verified</th></tr></thead><tbody><?php foreach($pricing as $x):?><tr><td><?=e($x['edition_name']?:'General')?></td><td><?=e(status_label($x['pricing_model']))?></td><td><?php if($x['amount_min']!==null){echo e(trim(($x['currency']?:'').' '.number_format((float)$x['amount_min'],2)));if($x['amount_max']!==null&&$x['amount_max']!=$x['amount_min'])echo ' – '.e(number_format((float)$x['amount_max'],2));if($x['unit_label'])echo ' / '.e($x['unit_label']);}else echo 'Contact vendor / not published';?></td><td><?=e(status_label($x['billing_period']))?></td><td><?=e($x['last_verified_at']?date('M j, Y',strtotime($x['last_verified_at'])):'Not recorded')?></td></tr><?php endforeach;?></tbody></table><?php else:?><div class="notice">TechSelectAI does not currently have verified public pricing for this product. We do not invent pricing; confirm the current commercial offer with the vendor.</div><?php endif;?></section>
<section class="section"><h2>Evidence sources</h2><p class="section-intro">TechSelectAI separates vendor/product facts from recommendation scoring. These sources support the published product data.</p><div class="evidence"><?php if(!$evidence):?><div class="notice">No published evidence sources are available yet.</div><?php else:foreach($evidence as $x):?><div class="source"><div class="source-icon">✓</div><div><a href="<?=e($x['source_url'])?>" rel="nofollow noopener" target="_blank"><strong><?=e($x['source_title'])?></strong></a><p><?=e($x['publisher_name']?:'Source')?> · <?=e(status_label($x['verification_status']))?> · <?=e(status_label($x['confidence']))?> confidence · checked <?=e($x['checked_at']?date('M j, Y',strtotime($x['checked_at'])):'date not recorded')?></p></div></div><?php endforeach;endif;?></div></section>
<?php if($alts):?><section class="section"><h2>Alternatives to <?=e($p['name'])?></h2><p class="section-intro">Other active products in the same TechSelectAI category.</p><div class="grid"><?php foreach($alts as $x):$pair=[$p['slug'],$x['slug']];sort($pair,SORT_STRING);?><div class="card"><div class="alt-head"><div class="mini-mark"><?=e(initials($x['name']))?></div><div><h3><a href="/software/<?=e($x['slug'])?>"><?=e($x['name'])?></a></h3></div></div><?php if($x['short_description']):?><p><?=e($x['short_description'])?></p><?php endif;?><p><a href="/compare/<?=e(implode('-vs-',$pair))?>">Compare with <?=e($p['name'])?> →</a></p></div><?php endforeach;?></div></section><?php endif;?>
<section class="cta"><div class="eyebrow">Independent software advice</div><h2>Is <?=e($p['name'])?> right for your company?</h2><p>TechSelectAI can evaluate it against your must-have capabilities, integrations, deployment constraints, security requirements, region and budget — then compare it with alternatives using the same evidence methodology.</p><a class="btn primary" href="/?considering=<?=rawurlencode($p['name'])?>">Evaluate <?=e($p['name'])?></a></section>
<footer>TechSelectAI uses evidence-backed product data. Unknown means not yet verified; it does not mean unsupported. Vendor names and trademarks belong to their respective owners.</footer></main></body></html>
